"""Basic vector operations."""

__version__ = "0.1.0"


def dotproduct(first: list[float | int], second: list[float | int]) -> float | int:
    """Return the dot product of two numeric lists."""
    return sum(left * right for left, right in zip(first, second))

"""Serve the locally built distributions through a small PEP 503 index."""

from __future__ import annotations

import argparse
import html
import mimetypes
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import unquote, urlsplit


PROJECT_NAME = "vectorops"
PROJECT_VERSION = "0.1.0"
ROOT = Path(__file__).resolve().parent
REPOSITORY = ROOT / "pypi"
PACKAGES = REPOSITORY / "packages"


class PackageIndexHandler(BaseHTTPRequestHandler):
    server_version = "vectorops-index/1.0"

    def _send(self, status: int, body: bytes, content_type: str) -> None:
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    def _package_files(self) -> list[Path]:
        return sorted(
            path
            for path in PACKAGES.iterdir()
            if path.is_file() and path.name.startswith(f"{PROJECT_NAME}-")
        ) if PACKAGES.is_dir() else []

    def _simple_index(self, project: str) -> None:
        if project != PROJECT_NAME:
            self._send(404, b"Not Found\n", "text/plain; charset=utf-8")
            return

        links = "\n".join(
            f'<a href="/packages/{html.escape(path.name, quote=True)}">'
            f"{html.escape(path.name)}</a>"
            for path in self._package_files()
        )
        body = (
            "<!DOCTYPE html>\n<html><body>\n"
            f"{links}\n"
            "</body></html>\n"
        ).encode()
        self._send(200, body, "text/html; charset=utf-8")

    def _package_file(self, filename: str) -> None:
        path = (PACKAGES / filename).resolve()
        if path.parent != PACKAGES.resolve() or not path.is_file():
            self._send(404, b"Not Found\n", "text/plain; charset=utf-8")
            return
        body = path.read_bytes()
        content_type = mimetypes.guess_type(path.name)[0] or "application/octet-stream"
        self._send(200, body, content_type)

    def do_GET(self) -> None:
        self._route()

    def do_HEAD(self) -> None:
        self._route()

    def _route(self) -> None:
        path = unquote(urlsplit(self.path).path)
        if path == "/simple":
            self.send_response(301)
            self.send_header("Location", "/simple/")
            self.send_header("Content-Length", "0")
            self.end_headers()
        elif path == "/simple/":
            body = f'<a href="{PROJECT_NAME}/">{PROJECT_NAME}</a>\n'.encode()
            self._send(200, body, "text/html; charset=utf-8")
        elif path == f"/simple/{PROJECT_NAME}":
            self.send_response(301)
            self.send_header("Location", f"/simple/{PROJECT_NAME}/")
            self.send_header("Content-Length", "0")
            self.end_headers()
        elif path == f"/simple/{PROJECT_NAME}/":
            self._simple_index(PROJECT_NAME)
        elif path.startswith("/packages/") and path.count("/") == 2:
            self._package_file(path.removeprefix("/packages/"))
        else:
            self._send(404, b"Not Found\n", "text/plain; charset=utf-8")


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, default=8080)
    args = parser.parse_args()

    PACKAGES.mkdir(parents=True, exist_ok=True)
    server = ThreadingHTTPServer((args.host, args.port), PackageIndexHandler)
    print(f"Serving {PROJECT_NAME} {PROJECT_VERSION} at http://{args.host}:{args.port}/simple", flush=True)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()


if __name__ == "__main__":
    main()
